import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  dataDictionaryV1ResultCodeSchema,
  type DataDictionaryV1ResultCode,
} from "./data-dictionary-v1-result-code.js";
import { type158Schema, type Type158 } from "./type158.js";

export type Action100 = {
  /** A unique identifier generated by Global Payments to identify an action. */
  id?: string;
  /** The type of action executed. */
  type?: Type158;
  /** Global Payments time indicating when the object was created in ISO-8601 format. */
  timeCreated?: Date;
  /** The result of the action executed. */
  resultCode?: DataDictionaryV1ResultCode;
  /** The id of the app that was used to create the token. */
  appId?: string;
  /** The name of the app the user gave to the application. */
  appName?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

const action100Properties: s.Shape<Action100> = {
  id: s.optional(s.string()),
  type: s.optional(s.lazy(() => type158Schema)),
  timeCreated: s.optional(s.dateTime()),
  resultCode: s.optional(s.lazy(() => dataDictionaryV1ResultCodeSchema)),
  appId: s.optional(s.string()),
  appName: s.optional(s.string()),
  _keysMap: {
    timeCreated: "time_created",
    resultCode: "result_code",
    appId: "app_id",
    appName: "app_name",
  },
};

export const action100InternalSchema: Schema<Action100> = s.object<Action100>(action100Properties, {
  additionalProperties: s.json(),
});

export const action100Schema: Schema<Action100> = s.lazySchema(() =>
  s.object<Action100>(
    {
      ...action100Properties,
      id: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      appId: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      appName: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
    },
    { additionalProperties: s.json() },
  ),
);
